.nav-lien {
  position: relative;
  text-decoration: none;
  color: #1a1a1a;
}

.nav-lien::after {
  content: "";
  position: absolute;
  left: 0;
  bottom: -4px;
  width: 100%;
  height: 2px;
  background: #0a7d33;
  transform: scaleX(0);
  transform-origin: left;
  transition: transform 0.25s ease;
}

.nav-lien:hover::after,
.nav-lien:focus-visible::after { transform: scaleX(1); }

@media (prefers-reduced-motion: reduce) {
  .nav-lien::after { transition: none; }
}

const modale = document.querySelector("#ma-modale");
const declencheur = document.querySelector("#ouvrir-modale");
const focusables = () => modale.querySelectorAll("button, a, input, [tabindex]:not([tabindex='-1'])");
let elementPrecedent = null;

function ouvrir() {
  elementPrecedent = document.activeElement;
  modale.hidden = false;
  focusables()[0].focus();
  document.addEventListener("keydown", gererTouche);
}

function fermer() {
  modale.hidden = true;
  document.removeEventListener("keydown", gererTouche);
  elementPrecedent?.focus();
}

function gererTouche(event) {
  if (event.key === "Escape") fermer();
  if (event.key !== "Tab") return;
  const elements = focusables();
  const premier = elements[0];
  const dernier = elements[elements.length - 1];
  if (event.shiftKey && document.activeElement === premier) {
    event.preventDefault();
    dernier.focus();
  } else if (!event.shiftKey && document.activeElement === dernier) {
    event.preventDefault();
    premier.focus();
  }
}

declencheur.addEventListener("click", ouvrir);
modale.addEventListener("click", (event) => {
  if (event.target === modale) fermer();
});
modale.querySelector("[data-fermer]").addEventListener("click", fermer);

const produits = [
  { nom: "Sac artisanal", categorie: "accessoires", prix: 25 },
  { nom: "T-shirt coton", categorie: "vetements", prix: 12 },
  { nom: "Collier perles", categorie: "accessoires", prix: 40 },
  { nom: "Casquette", categorie: "vetements", prix: 15 },
];

const selectCategorie = document.querySelector("#categorie");
const rangePrix = document.querySelector("#prix-max");
const compteur = document.querySelector("#compteur");
const liste = document.querySelector("#resultats");

function appliquerFiltre() {
  const categorie = selectCategorie.value;
  const prixMax = Number(rangePrix.value);
  const visibles = produits.filter((p) =>
    (categorie === "tous" || p.categorie === categorie) && p.prix <= prixMax
  );
  liste.innerHTML = visibles
    .map((p) => `<li>${p.nom} — ${p.prix} €</li>`)
    .join("");
  compteur.textContent = `${visibles.length} résultat(s)`;
}

selectCategorie.addEventListener("change", appliquerFiltre);
rangePrix.addEventListener("input", appliquerFiltre);
appliquerFiltre();

type Statut = "succes" | "attente" | "erreur";

const CONFIG: Record<Statut, { libelle: string; classes: string }> = {
  succes: { libelle: "Succès", classes: "bg-green-100 text-green-800" },
  attente: { libelle: "En attente", classes: "bg-orange-100 text-orange-800" },
  erreur: { libelle: "Erreur", classes: "bg-red-100 text-red-800" },
};

interface BadgeStatutProps {
  statut: Statut;
  className?: string;
}

export function BadgeStatut({ statut, className = "" }: BadgeStatutProps) {
  const { libelle, classes } = CONFIG[statut];
  return (
    <span
      className={`inline-block rounded-full px-2.5 py-0.5 text-xs font-semibold ${classes} ${className}`}
    >
      {libelle}
    </span>
  );
}

